import logging
from threading import Lock
from queue import Queue

class ErrorLogger:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.verbosity_level = "INFO"
        self.error_codes = {
            "RESOURCE_EXHAUSTION": 403,
            "API_CALL_FAILURE": 500,
            "DATA_CORRUPTION": 502,
            "AUTHENTICATION_ISSUE": 401,
            "NETWORK_OUTAGE": 503
        }
        self.queue = Queue()
        self.lock = Lock()

    def set_verbosity(self, level):
        self.verbosity_level = level

    def log_error(self, error_type, message, data=None):
        if self.verbosity_level in ("DEBUG", "INFO", "WARNING"):
            with self.lock:
                self.queue.put((error_type, message, data))
        elif self.verbosity_level == "ERROR":
            print(f"Error Type: {error_type}, Message: {message}")

    def start_logging_thread(self):
        thread = threading.Thread(target=self._process_log_queue)
        thread.daemon = True
        thread.start()

    def _process_log_queue(self):
        while True:
            try:
                error_type, message, data = self.queue.get(block=True, timeout=5)
                if error_type in self.error_codes:
                    logging.error(f"Error Type: {error_type}, Code: {self.error_codes[error_type]}, Message: {message}, Data: {data}")
                else:
                    logging.warning(f"Unknown Error Type: {error_type}, Message: {message}, Data: {data}")
            except queue.Empty:
                # Timeout handling - log a warning or retry later
                pass



