#include <memory>
#include <forward_list>
#include <mutex>

// Placeholder for your external logging interface
class Logger {
 public:
  virtual void Log(LogLevel level, const std::string& message) = 0;
};

template <typename T>
class ThreadSafeForwardList {
 public:
  using iterator = typename forward_list<T>::iterator;

  std::mutex mutex_;
  forward_list<T> data_;

  iterator begin() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return data_.begin();
  }

  iterator end() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return data_.end();
  }

  void insertAfter(iterator position, const T& value) {
    std::lock_guard<std::mutex> lock(mutex_);
    data_.insert(position, value);
  }

  void push_back(const T& value) {
    std::lock_guard<std::mutex> lock(mutex_);
    data_.push_back(value);
  }
};

// Function implementation 
bool appendOrInsertAfter(ThreadSafeForwardList<std::string>& list, const std::string& searchString, const std::string& insertString, LogLevel logLevel, Logger* logger) {
  auto it = list.begin();
  while (it != list.end() && *it != searchString) {
    ++it;
  }

  if (it != list.end()) {
    list.insertAfter(it, insertString);
    return true;
  } else {
    list.push_back(insertString);
    // Log the insertion failure if logLevel permits
    if (logLevel == LogLevel::Error) {
      logger->Log(LogLevel::Error, "Insertion failed: String '" + searchString + "' not found in list.");
    }
    return false;
  }
}
```



