    public async Task<IActionResult> ExecuteParameterizedQueryAsync(ExecuteQueryRequest request)
    {
        if (!ValidateConfiguration(request))
        {
            return new BadRequestObjectResult("Invalid configuration.");
        }

        try
        {
            using (var connection = new SqlConnection(request.ConnectionString))
            {
                await connection.OpenAsync();

                // Build parameterized SQL command
                var command = new SqlCommand(request.SqlCommand, connection);

                // Add parameters to the command
                foreach (var parameter in request.Parameters)
                {
                    command.Parameters.AddWithValue(parameter.Key, parameter.Value);
                }

                // Execute the query and process results asynchronously
                using (var reader = await command.ExecuteReaderAsync())
                {
                    while (await reader.ReadAsync())
                    {
                        // Process each row using the callback function
                        request.CallbackFunction(reader);
                    }
                }
            }

            return new OkObjectResult("Query executed successfully.");
        }
        catch (SqlException ex)
        {
            LogException($"Database error: {ex.Message}", request.ConnectionString, ex);
            return new StatusCodeResult(500); 
        }
        catch (Exception ex)
        {
            LogException($"Unexpected error: {ex.Message}", request.ConnectionString, ex);
            return new StatusCodeResult(500);  
        }
