function renderFooterScripts(scripts) {
  const footer = document.getElementById('footer'); 
  if (!footer) {
    console.error('Error: "footer" element not found.');
    return;
  }

  scripts.forEach((script, index) => {
    if (!script.key || !script.code) {
      console.warn(`Warning: Script ${index + 1} is missing key or code.`);
      return;
    }

    const scriptElement = document.createElement('script');
    scriptElement.key = script.key; // Store key for tracking
    Object.assign(scriptElement, script);  

    // Handle attributes like async, defer, noModule
    scriptElement.async = script.async || false; 
    scriptElement.defer = script.defer || false; 
    scriptElement.noModule = script.noModule || false; 

    // Analytics tracking (example)
    scriptElement.onload = () => {
      if (script.trackingId) {
        // Send analytics event with script key and trackingId
      }
    };

    footer.appendChild(scriptElement); 
  });

  return footer.innerHTML; // Return the rendered HTML string 
}
```



