function refreshDialogFields(resourceId, url) {
  const fieldMapping = {
    'field1': 'api/data1',
    'field2': 'api/data2',
    // ... add more fields and their API endpoints
  };

  const cache = {};
  let requestCount = 0;

  const updateField = async (fieldId) => {
    const apiEndpoint = fieldMapping[fieldId];
    const cachedData = cache[fieldId];

    if (cachedData && Date.now() - cachedData.timestamp < 300000) { // Cache valid for 5 minutes
      return;
    }

    requestCount++;
    if (requestCount > 100) {
      console.log('Rate limiting reached, pausing requests.');
      return;
    }

    try {
      const response = await fetch(url + apiEndpoint);
      const data = await response.json();

      cache[fieldId] = { data: data, timestamp: Date.now() };

      // Update dialog field in child window
      console.log(`Updated field ${fieldId} with value:`, data);
    } catch (error) {
      console.error(`Error fetching data for ${fieldId}:`, error);
      if (retries < 3) {
        retries++;
        setTimeout(() => updateField(fieldId), 1000); // Retry after 1 second
      } else {
        console.warn(`Max retries reached for ${fieldId}`);
      }
    }
  };

  const textFromParent = parentWindow.postMessage('GetText', '*');

  // Count occurrences of Old Testament books
