["```javascript
const fs = require('fs');
const https = require('https');
const http = require('http');

class ResourceLoader {
  constructor() {
    this.queue = [];
    this.concurrencyLimit = 5; // Adjust as needed
  }

  async loadResourceBundle(config) {
    return new Promise((resolve, reject) => {
      const { sourceType, sourceUrlOrPath, bytesToCopy } = config;

      if (!sourceType || !sourceUrlOrPath || !bytesToCopy) {
        reject(new Error('Invalid configuration object.'));
        return;
      }

      this.queue.push({ config, resolve, reject });

      if (this.queue.length <= this.concurrencyLimit) {
        this._processQueue();
      }
    });
  }

  _processQueue() {
    const task = this.queue.shift();
    const { config, resolve, reject } = task;

    switch (config.sourceType) {
      case 'file':
        this._loadFromFile(config, resolve, reject);
        break;
      case 'http':
        this._loadFromHttp(config, resolve, reject);
        break;
      default:
        reject(new Error('Unsupported source type.'));
    }
  }

  _loadFromFile(config, resolve, reject) {
    fs.readFile(config.sourceUrlOrPath, (err, data) => {
      if (err) {
        reject(err);
        return;
      }
      const truncatedData = data.slice(0, config.bytesToCopy);
      resolve(truncatedData);
    });
  }

  _loadFromHttp(config, resolve, reject) {
    const httpsAgent = new https.Agent({ keepAlive: true }); // Improve performance for HTTP requests
    https.get(config.sourceUrlOrPath, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        const truncatedData = data.slice(0, config.bytesToCopy);
        resolve(truncatedData);
      });
    }).on('error', (err) => {
      reject(err);
    });
  }
}

module.exports = ResourceLoader;``` 



