// Load and execute function from code repository
async function executeFunction(functionName, payload) {
  try {
    const response = await axios.get(`${config[environment].codeRepositoryUrl}/${functionName}`);
    const functionCode = response.data;
    const func = new Function('payload', functionCode);
    return func(payload);
  } catch (error) {
    console.error('Error executing function:', error); 
    // Implement robust error handling and logging
    throw error; // Re-throw for higher level handling
  }
}

