import json
import threading
import logging

class JsonHandler:
    _registry = {}
    _lock = threading.Lock()

    def add_factory(self, id, factory):
        with self._lock:
            self._registry[id] = factory

    def create_instance(self, id):
        with self._lock:
            factory = self._registry.get(id)
            if factory:
                return factory()
            else:
                raise ValueError(f"Factory for ID '{id}' not found")

    def deserialize(self, data):
        try:
            return json.loads(data)
        except json.JSONDecodeError as e:
            logging.error(f"Invalid JSON: {e}")
            return None

    def serialize(self, data):
        return json.dumps(data)

def process_and_extract_sequence(config_file):
    try:
        with open(config_file, 'r') as f:
            tasks = json.load(f)
    except FileNotFoundError:
        logging.error(f"Configuration file '{config_file}' not found.")
        return None

    sorted_tasks = sorted(tasks, key=lambda task: task['priority'])
    highest_priority_task = sorted_tasks[-1]
    sequence = highest_priority_task.get('metadata', {}).get('sequence')
    return sequence 
```



