class CommandManager {
private:
  std::queue<Command> commandQueue;
  std::mutex queueMutex;
  std::condition_variable queueCondition;
  int maxConcurrentProcesses = 10; // Adjust as needed

  void executeCommand(const Command& cmd) {
    // Execute shell command using std::system or similar library.
    // Handle errors and logging appropriately.
  }

public:
  void addCommand(const Command& cmd) {
    std::lock_guard<std::mutex> lock(queueMutex);
    commandQueue.push(cmd);
    queueCondition.notify_one();
  }

  void start() {
    for (int i = 0; i < maxConcurrentProcesses; ++i) {
      std::thread worker([this]() {
        while (true) {
          Command cmd;
          {
            std::unique_lock<std::mutex> lock(queueMutex);
            queueCondition.wait(lock, [this] { return !commandQueue.empty(); });
            cmd = commandQueue.front();
            commandQueue.pop();
          }
          executeCommand(cmd);
        }
      });
      worker.detach(); // Allow threads to manage their own lifetime
    }
  }
};

struct Command {
