    private final ToolManager toolManager; 

    public BatchProcessor() {
        toolManager = new ToolManager(); // Initialize with your plugin architecture
    }

    public void processBatch(String taskId, String dataPath) {
        executor.submit(() -> {
            try {
                // Handle job submission to queue and log details (implementation omitted)

                Tool tool = toolManager.getTool("your_tool_name"); // Fetch the plugin
                if (tool == null) {
                    throw new RuntimeException("Tool not found: " + "your_tool_name"); 
                }

                for (int attempt = 1; attempt <= 3; attempt++) {
                    try {
                        // Execute the command with retries and backoff logic
                        tool.execute(dataPath);
                        logSuccess("Job {} completed successfully", taskId); 
                        return; // Exit loop on success
                    } catch (Exception e) {
                        logAttemptFailure(taskId, attempt, e);
                        sleepExponentially(attempt);
                    }
                }

                // Log failure after retries and handle cleanup
                logFatalError("Job {} failed after 3 attempts", taskId);
            } catch (Exception e) {
                logError(e, taskId); // Handle unexpected exceptions
            } finally {
                // Cleanup resources 
            }
        });
    }

    private void logSuccess(String message, String taskId) {
        System.out.println(String.format(message, taskId));
    }

    private void logAttemptFailure(String taskId, int attempt, Exception e) {
        System.err.println(String.format("Job %s: Attempt %d failed - %s", taskId, attempt, e.getMessage()));
    }

    private void logFatalError(String message, String taskId) {
        System.err.println(String.format(message, taskId));
    }

    private void logError(Exception e, String taskId) {
        e.printStackTrace(); // Log stack trace for debugging
        System.err.println("Job " + taskId + " encountered an error.");
    }

    private void sleepExponentially(int attempt) {
        try {
            TimeUnit.SECONDS.sleep(Math.pow(2, attempt));
        } catch (InterruptedException ex) {
            Thread.currentThread().interrupt(); 
        }
    }


    public static void main(String[] args) {
        BatchProcessor processor = new BatchProcessor();

        // Process jobs (implementation omitted)
    }
}



