using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class Decryptor 
{
    private readonly IKeyProvider _keyProvider;
    private readonly IBinaryFormatter _binaryFormatter;

    public Decryptor(IKeyProvider keyProvider, IBinaryFormatter binaryFormatter)
    {
        _keyProvider = keyProvider;
        _binaryFormatter = binaryFormatter;
    }

    public T DecryptAndDeserialize<T>(string filePath, string encryptionKey, byte[] iv) 
    {
        try 
        {
            using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
            {
                byte[] encryptedData = ReadFully(fileStream);

                // Decrypt the data using AES-CBC
                byte[] decryptedData = AesCbcDecrypt(encryptedData, encryptionKey, iv);

                // Deserialize the decrypted data into the specified type
                return _binaryFormatter.Deserialize<T>(decryptedData);
            } 
        }
        catch (Exception ex) 
        {
            throw new DecryptionException($"Error decrypting and deserializing file: {ex.Message}", ex);
        }
    }

    private byte[] AesCbcDecrypt(byte[] encryptedData, string encryptionKey, byte[] iv)
    {
        using (var aes = Aes.Create()) 
        {
            aes.Key = Encoding.UTF8.GetBytes(encryptionKey);
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            using (var decryptor = aes.CreateDecryptor()) 
            {
                return decryptor.TransformFinalBlock(encryptedData, 0, encryptedData.Length);
            }
        }
    }

    private byte[] ReadFully(Stream stream) 
    {
        byte[] buffer = new byte[4096];
        using (MemoryStream ms = new MemoryStream()) 
        {
            int read;
            while ((read = stream.Read(buffer, 0, buffer.Length)) > 0) 
            {
                ms.Write(buffer, 0, read);
            }
            return ms.ToArray();
        }
    }
}

public interface IKeyProvider
{
    string GetEncryptionKey();
}

public interface IBinaryFormatter
{
    T Deserialize<T>(byte[] data);
}



