    private final int chunkSize = 4096; // Adjust as needed
    private final HashAlgorithm defaultAlgorithm = HashAlgorithm.SHA_256; // Default algorithm to use

    public interface HashAlgorithm {
        String getAlgName();
        MessageDigest getInstance() throws NoSuchAlgorithmException;
    }

    // ... (Implement HashAlgorithm for MD5 and SHA-256)

    public void processFile(final String filePath, final HashAlgorithm algorithm) {
        executor.submit(() -> {
            try (FileInputStream inputStream = new FileInputStream(filePath)) {
                MessageDigest digest = algorithm.getInstance();
                byte[] buffer = new byte[chunkSize];
                int bytesRead;
                while ((bytesRead = inputStream.read(buffer)) != -1) {
                    digest.update(buffer, 0, bytesRead);
                }
                String hash = getHashString(digest);
                // ... (Log or store the hash value)
            } catch (IOException | NoSuchAlgorithmException e) {
                // ... (Handle errors with logging, retry mechanisms, etc.)
            }
        });
    }

    private String getHashString(MessageDigest digest) {
        byte[] hashBytes = digest.digest();
        return String.format("%032x", new BigInteger(1, hashBytes)); 
    }


