import io.micronaut.http.annotation.*;
import io.micronaut.inject.qualifiers.Qualifiers;
import io.micronaut.runtime.Micronaut;

@Controller("/pokemon")
public class PokemonService {

    private final TypeApiService typeApiService;
    private final NameApiService nameApiService;
    private final BalanceApiService balanceApiService;
    private final CacheManager cacheManager;

    // Inject required services
    @Inject
    public PokemonService(TypeApiService typeApiService, NameApiService nameApiService, 
                          BalanceApiService balanceApiService, CacheManager cacheManager) {
        this.typeApiService = typeApiService;
        this.nameApiService = nameApiService;
        this.balanceApiService = balanceApiService;
        this.cacheManager = cacheManager;
    }

    @Get("/{name}")
    public Pokemon getPokemonDetails(@Param("name") String name) {
        // Retrieve cached data first
        Pokemon cachedPokemon = cacheManager.get(name);
        if (cachedPokemon != null) {
            return cachedPokemon;
        }

        // Fetch data from external APIs if not cached
        Type type = typeApiService.getTypeByName(name); 
        String nameData = nameApiService.getNameById(name);
        BalanceData balanceData = balanceApiService.getBalanceByTypeName(type.getName());

        // Construct Pokemon object and cache it
        Pokemon pokemon = new Pokemon(name, type, nameData, balanceData);
        cacheManager.put(name, pokemon); 

        return pokemon;
    }


}



