#include <mutex> 

std::forward_list<std::string>  myForwardList; 
std::mutex mtx;

void insertAfterInDynamicStringList(const std::string& firstStr, const std::string& secondStr) {
    mtx.lock();
    auto it = myForwardList.before_begin();
    for (; it != myForwardList.end(); ++it) {
        if (*it == firstStr) {
            myForwardList.insert_after(it, secondStr);
            mtx.unlock();
            return;
        }
    }
    myForwardList.push_back(secondStr); 
    mtx.unlock();
}
```


