['```csharp
public async Task<HttpResponseMessage> ExecuteParameterizedQueryAsync(ExecuteQueryRequest request)
{
    if (!ValidateConfiguration(request))
    {
        return Request.CreateResponse(HttpStatusCode.BadRequest, "Invalid configuration.");
    }

    try
    {
        using (var connection = new SqlConnection(request.ConnectionString))
        {
            await connection.OpenAsync();

            // Build parameterized SQL command
            var command = new SqlCommand(request.SqlCommand, connection);
            foreach (var parameter in request.Parameters)
            {
                command.Parameters.AddWithValue($"@{parameter.Key}", parameter.Value);
            }

            using (var reader = await command.ExecuteReaderAsync())
            {
                // Process results and invoke callback function
                while (await reader.ReadAsync())
                {
                    request.CallbackFunction(reader);
                }
            }
        }
    }
    catch (SqlException ex)
    {
        Log($"Database error: {ex.Message}");
        return Request.CreateResponse(HttpStatusCode.InternalServerError, "Database error occurred.");
    }
    catch (Exception ex)
    {
        Log($"Unexpected error: {ex.Message}");
        return Request.CreateResponse(HttpStatusCode.InternalServerError, "An unexpected error occurred.");
    }

    return Request.CreateResponse(HttpStatusCode.OK, "Query executed successfully.");
}

private bool ValidateConfiguration(ExecuteQueryRequest request)
{
