function updateClinicStatus($clinicId) {
  // Initialize semaphore using Redis
  $semaphore = new RedisSemaphore('clinic_update_' . $clinicId); 

  // Acquire semaphore
  if ($semaphore->acquire()) {
    try {
      // Retrieve latest status from external services
      $status = getExternalServiceStatus($clinicId); 

      // Update database table with status, IP address, and timestamp
      $db = new PDO('...', '', ''); // Connect to database
      $stmt = $db->prepare("UPDATE clinics SET status=:status, last_modified_ip=:ip, last_modified_timestamp=NOW() WHERE id=:id");
      $stmt->execute([':status' => $status, ':ip' => $_SERVER['REMOTE_ADDR'], ':id' => $clinicId]);

      // Log success
      logSuccess('Clinic status updated successfully.', $clinicId);

    } catch (Exception $e) {
      // Handle database errors and transaction rollbacks
      logError('Error updating clinic status:', $e, $clinicId);
    } finally {
      $semaphore->release(); // Release semaphore after completion
    }
  } else {
    logError('Semaphore acquisition failed. Retrying later.', $clinicId);
  } 

}

?>
