public class MoSTStateLoader {

    private static final ConcurrentHashMap<String, MoSTState> stateCache = new ConcurrentHashMap<>();

    public static synchronized MoSTState loadMoSTState(String filePath) throws MoSTStateException {
        if (stateCache.containsKey(filePath)) {
            return stateCache.get(filePath);
        }

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            MoSTState moSTState = (MoSTState) ois.readObject();
            moSTState.initializeServices(); // Initialize external services asynchronously
            stateCache.put(filePath, moSTState);
            return moSTState;

        } catch (IOException | ClassNotFoundException e) {
            throw new MoSTStateException("Failed to load MoSTState from file", e);
        }
    }

}

