#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h> 

typedef struct {
    char interface_name[32];
    unsigned long received_bytes;
    unsigned long transmitted_bytes;
    unsigned long error_count;
    time_t timestamp;
} NICReport;

typedef struct {
    NICReport* reports;
    size_t capacity; 
    size_t size; 
    pthread_mutex_t mutex;
} NICStatisticsManager;

NICStatisticsManager* createNICStatisticsManager(size_t initialCapacity) {
    NICStatisticsManager* manager = malloc(sizeof(NICStatisticsManager));
    manager->reports = malloc(initialCapacity * sizeof(NICReport));
    manager->capacity = initialCapacity; 
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void addNICReport(NICStatisticsManager* manager, NICReport report) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size < manager->capacity) {
        manager->reports[manager->size] = report;
        manager->size++; 
    } else {
        // Handle capacity overflow - retry later? log error?
        printf("NIC Report Buffer Full!\n"); 
    }
    pthread_mutex_unlock(&manager->mutex);
}

NICReport* getNICReportByInterface(NICStatisticsManager* manager, const char* interfaceName) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->size; i++) {
        if (strcmp(manager->reports[i].interface_name, interfaceName) == 0) {
            pthread_mutex_unlock(&manager->mutex);
            return &manager->reports[i];
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return NULL; // Interface not found
}


// ... Other functions for aggregate statistics, error handling, external monitoring service integration

