-- Stored Procedure
CREATE PROCEDURE dbo.GetPaginatedEmployees (
    @SupervisorID INT = NULL,
    @Department VARCHAR(50) = NULL,
    @JobTitle VARCHAR(100) = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 10
)
AS
BEGIN
    -- Filtering logic based on parameters

    SELECT *
    FROM Employees
    WHERE (SupervisorID = @SupervisorID OR @SupervisorID IS NULL)
      AND (Department = @Department OR @Department IS NULL)
      AND (JobTitle LIKE '%' + @JobTitle + '%')  
    ORDER BY EmployeeID
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;

END;
