    public EmployeeProcessorService(ILogger<EmployeeProcessorService> logger, 
                                    IDbConnectionFactory dbConnectionFactory, 
                                    IMessageQueueClient messageQueueClient)
    {
        _logger = logger;
        _dbConnectionFactory = dbConnectionFactory;
        _messageQueueClient = messageQueueClient;
    }

    public async Task ProcessEmployeesAsync()
    {
        var consumer = _messageQueueClient.CreateConsumer();

        await foreach (var message in consumer.ReceiveMessagesAsync())
        {
            try
            {
                // Deserialize filtering criteria from message
                var filteringParams = JsonConvert.DeserializeObject<FilteringCriteria>(message.Body);

                using var connection = _dbConnectionFactory.CreateConnection();
                connection.Open();

                await connection.ExecuteAsync("dbo.GetPaginatedEmployees", 
                                            new { SupervisorID = filteringParams.SupervisorId, 
                                                  Department = filteringParams.Department, 
                                                  JobTitle = filteringParams.JobTitle });

            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing employee records.");

                // Handle retries and timeouts
            }
        }
    }
}




