    public class RandomNumberGeneratorPool
    {
        private readonly Dictionary<Type, RNG> _rngs = new();

        public T GetRng<T>(int seed) where T : RNG
        {
            if (!_rngs.TryGetValue(typeof(T), out var rng))
            {
                rng = Activator.CreateInstance<T>();
                _rngs[typeof(T)] = rng;
            }

            rng.SetSeed(seed);
            return (T)rng;
        }
    }

    public interface RNG
    {
        void SetSeed(int seed);
        int NextInt(int min, int max);
        double NextDouble(double min, double max);
