class CommandScheduler {
public:
    CommandScheduler(int maxThreads) : maxThreads(maxThreads) {} 

    void addCommand(const Command& cmd) {
        // Acquire lock before modifying shared data
        std::lock_guard<std::mutex> lock(queueMutex);

        commandQueue.push(cmd); // Enqueue the command
        cv.notify_one();      // Notify a worker thread to process 
    }

    void run() {
        for (int i = 0; i < maxThreads; ++i) {
            std::thread worker([this]() {
                while (true) {
                    std::unique_lock<std::mutex> lock(queueMutex);
                    cv.wait(lock, [this]{ return !commandQueue.empty(); }); // Wait until a command is available

                    Command cmd = commandQueue.front(); 
                    commandQueue.pop();
                    lock.unlock();

                    // Simulate execution and handle results
                    std::cout << "Executing: " << cmd.cmd << std::endl; 

                    // Replace with actual shell command execution logic
                }
            });

            worker.detach(); // Allow worker threads to run independently
        }
    }

private:
    int maxThreads;
    std::queue<Command> commandQueue;
    std::mutex queueMutex;
    std::condition_variable cv; 
};



int main() {
    CommandScheduler scheduler(10); // Create scheduler with 10 worker threads
    scheduler.run();

