    }

private:
    void processReports() {
        while (true) {
            std::unique_lock<std::mutex> lock(m_reportsMutex);
            m_cv.wait(lock, [this]{ return !m_reportsQueue.empty(); }); 

            MetricReport report = m_reportsQueue.front();
            m_reportsQueue.pop();
            lock.unlock();

            // Process the report (store it, analyze it, send to aggregators) 
            // ...
        }
    }

    std::queue<MetricReport> m_reportsQueue;
    std::mutex m_reportsMutex;
    std::condition_variable m_cv;
    std::thread m_reportProcessorThread; // Thread for processing reports

};




int main() {
