public class FileHashingComponent {

    private static final Logger logger = LoggerFactory.getLogger(FileHashingComponent.class);

    // ... (Configuration, API methods, and other components omitted) 


    public String calculateMD5(String filePath) throws IOException,NoSuchAlgorithmException {
        FileInputStream fileInputStream = new FileInputStream(filePath);
        MessageDigest md5Digest = MessageDigest.getInstance("MD5");
        byte[] buffer = new byte[4096]; // Adjust buffer size as needed

        int bytesRead;
        while ((bytesRead = fileInputStream.read(buffer)) != -1) {
            md5Digest.update(buffer, 0, bytesRead);
        }
        fileInputStream.close();

        byte[] md5Bytes = md5Digest.digest();
        return String.format("%032x", new BigInteger(1, md5Bytes));
    }


    // ... (Other methods for SHA-256 calculation, API methods, and error handling) 
}



