package com.ecommerce.inventory;

import java.util.concurrent.atomic.AtomicInteger;

public class InventoryManager {
    private Map<Long, AtomicInteger> productStock = new ConcurrentHashMap<>();

    public void updateStock(Long productId, int quantity) {
        productStock.computeIfAbsent(productId, k -> new AtomicInteger(0)).addAndGet(quantity);
    }

    public int getStockLevel(Long productId) {
        return productStock.getOrDefault(productId, new AtomicInteger(0)).get();
    }
}



