const authenticationService = require('./authenticationService');

app.get('/execute/:functionName', async (req, res) => {
  const { functionName } = req.params;
  const user = await authenticationService.authenticate(req);

  if (!user || !user.permissions.includes('EXECUTE_FUNCTIONS')) {
    return res.status(403).send('Unauthorized');
  }

  const environment = process.env.NODE_ENV; 

  try {
    const functionCode = await functionManager.loadFunction(functionName, environment);
    const result = await functionManager.executeFunction(functionCode, req.query, user);
    res.send(result);
  } catch (error) {
    console.error('Error executing function:', error);
    res.status(500).send('Function execution failed');
  }
});

