# Dynamic task scheduling example (using a simplified scheduler)
class Scheduler:
    def __init__(self):
        self.tasks = {}

    def schedule_task(self, name, func, trigger_time):
        self.tasks[name] = {'func': func, 'trigger_time': trigger_time}

    async def run(self):
        while True:
            now = datetime.datetime.now()
            for task_name, task_data in self.tasks.items():
                if now >= task_data['trigger_time']:
                    await asyncio.create_task(task_data['func']()) 

# Example usage
scheduler = Scheduler()
scheduler.schedule_task('process_data', process_data, datetime.datetime.now() + timedelta(minutes=1))


# Run the worker
if __name__ == '__main__':
    asyncio.run(app.worker_main())
