namespace RealtimeEventStreamProcessor
{
    public class EventProcessor
    {
        private readonly IMessageBroker _messageBroker;
        private readonly IDatabaseClient _databaseClient;
        private readonly IEventProcessorEngine _processorEngine;

        public EventProcessor(IMessageBroker messageBroker, IDatabaseClient databaseClient, IEventProcessorEngine processorEngine)
        {
            _messageBroker = messageBroker;
            _databaseClient = databaseClient;
            _processorEngine = processorEngine;
        }

        public async Task StartProcessingAsync()
        {
            while (true)
            {
                var events = await _messageBroker.ReceiveEventsAsync();

                foreach (var @event in events)
                {
                    await ProcessEvent(@event);
                }
            }
        }

        private async Task ProcessEvent(Event @event)
        {
            var processedData = await _processorEngine.Process(@event);

            await _databaseClient.StoreProcessedDataAsync(processedData);
        }
    }
}
