        private readonly IDictionary<string, Func<string, byte[]>> _hashAlgorithms = new Dictionary<string, Func<string, byte[]>>()
        {
            {"MD5", (input) => MD5.CalculateHash(input)}, 
            {"SHA256", (input) => SHA256.CalculateHash(input)}
        };

        public HashingService(ILoggingService loggingService)
        {
            _loggingService = loggingService;
        }

        public async Task<string> GenerateHashAsync(string input, string algorithm) 
        {
            if (!_hashAlgorithms.ContainsKey(algorithm))
            {
                throw new ArgumentException("Unsupported hashing algorithm.");
            }

            try
            {
                byte[] hash = _hashAlgorithms[algorithm](input);
                return Convert.ToBase64String(hash);
            }
            catch (Exception ex)
            {
                _loggingService.Log($"Error generating hash for '{input}' using algorithm '{algorithm}': {ex.Message}");
                throw; 
            }
        }

        // Add more methods for validation, algorithm registration, etc.
    }
}



