public class FallbackStrategy
{
    private readonly List<IDataSource> _dataSources; // Ordered by priority 

    // ... Constructor and methods to select data source based on conditions ...

    public async Task<Metadata> GetMetadataAsync(IMemoryCache cache, string filePath)
    {
        var cachedMetadata = cache.Get(filePath); 
        if (cachedMetadata != null)
        {
            return cachedMetadata; // Return cached metadata if available
        }

        // ... Iterate through data sources using _dataSources ordering ...
        foreach (var source in _dataSources)
        {
            try 
            {
                var retrievedMetadata = await source.GetMetadataAsync(filePath);
                cache.Set(filePath, retrievedMetadata, TimeSpan.FromMinutes(5)); // Cache for a while
                return retrievedMetadata;  
            } 
            catch (Exception)
            {
                // ... Handle transient errors gracefully using retry mechanism or fallback to next source ...
            } 
        }

        // If no successful retrieval, return default metadata or throw an exception
    }   
}



```

