#include <list>
#include <mutex>

std::forward_list<std::string> configuration;
std::mutex configMutex;

void InsertOrAppendConfigEntry(const std::string& targetKey, const std::string& newEntry) {
    std::lock_guard<std::mutex> lock(configMutex);
    auto it = configuration.begin();

    while (it != configuration.end()) {
        if (*it == targetKey) {
            configuration.insert(it++, newEntry);
            return;
        }
        ++it;
    }

    configuration.push_back(newEntry);
} 
