// api.service.ts
import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, of, throwError } from 'rxjs';
import { retryWhen, delayWhen, catchError, tap } from 'rxjs/operators';

@Injectable({
  providedIn: 'root'
})
export class ApiService {

  constructor(private http: HttpClient) {}

  // Method to make API calls with retries and backoff logic
  fetchData(url: string): Observable<any> {
    return this.http.get(url).pipe(
      retryWhen(errors => errors.pipe(
        delayWhen(() => of(2000)), // Delay between retries based on system load
        tap(() => console.log('Retry attempt...'))
      )),
      catchError(error => {
        console.error('API error:', error);
        return throwError('Network Error'); 
      })
    );
  }

}



