pub struct ApiClient {
    client: Client,
    disable_cert_validation: bool,
}

impl ApiClient {
    pub fn new(disable_cert_validation: bool) -> Result<Self, String> {
        let client = Client::new();
        Ok(Self {
            client,
            disable_cert_validation,
        })
    }

    pub fn request(&self, url: &str) -> Result<RequestBuilder, String> {
        let req = self.client
            .get(url)
            .send()
            .map_err(|e| format!("Request failed: {}", e))?;

        Ok(RequestBuilder {
            response: req,
        })
    }
}

pub struct RequestBuilder {
    response: reqwest::Response,
}

impl RequestBuilder {
    pub async fn into_json(&self) -> Result<Value, String> {
        let bytes = self.response.bytes().await.map_err(|e| format!("Failed to read response body: {}", e))?;
        serde_json::from_slice(&bytes).map_err(|e| format!("Failed to parse JSON response: {}", e))
    }

    // Add more methods as needed for handling the request
}


``` 


