        while (true) {
            std::unique_lock<std::mutex> lock(processing_queue_mutex_);
            cv_.wait(lock, [this] { return !processing_queue_.empty() || shutdown_; });
            if (shutdown_) {
                break;
            }

            // Process log entries here. 

