#include <queue>
#include <mutex>
#include <condition_variable>

class NetworkDataProcessor {
public:
    NetworkDataProcessor() : _isRunning(true) {}

    void start() {
        std::thread consumerThread(&NetworkDataProcessor::consumeData, this);
        consumerThread.detach();
    }

    void stop() {
        _isRunning = false;
    }

    void enqueueData(const std::string& data) {
        std::unique_lock<std::mutex> lock(_dataQueueMutex);
        _dataQueue.push(data);
        _cv.notify_one();
    }

private:
    void consumeData() {
        while (_isRunning) {
            std::unique_lock<std::mutex> lock(_dataQueueMutex);
            _cv.wait(lock, [this] { return !_dataQueue.empty() || !_isRunning; });

            if (!_isRunning) {
                break;
            }

            std::string data = _dataQueue.front();
            _dataQueue.pop();
            lock.unlock();

            // Process the data here...
            std::cout << "Processing: " << data << std::endl;
        }
    }

    std::queue<std::string> _dataQueue;
    std::mutex _dataQueueMutex;
    std::condition_variable _cv;
    bool _isRunning;
};


int main() {
    NetworkDataProcessor processor;
    processor.start();

    // Enqueue some data
    processor.enqueueData("HTTP Request");
    processor.enqueueData("WebSocket Message");
    processor.enqueueData("DNS Query");

    std::this_thread::sleep_for(std::chrono::seconds(5)); 
    processor.stop();

    return 0;
}
