int runCommandInBackground(const char* command) {
  pid_t pid = fork();
  if (pid == 0) { // Child process
    execlp(command, command, NULL);
    perror("Error executing command");
    exit(1);
  } else if (pid > 0) { // Parent process
    int status;
    wait(&status);
    return WIFEXITED(status) && WEXITSTATUS(status) == 0; 
  } else {
    // Fork failed
    perror("Fork error");
    return 0;
  }
}

```



