void insertStringAfter(std::forward_list<std::string>& list, const std::string& target, const std::string& insertion) {
    auto it = list.begin();
    while (it != list.end() && *it != target) {
        ++it;
    }

    if (it != list.end()) {
        list.insert(it, insertion); 
    } else {
        list.push_back(insertion);
    }
}

