    use super::*;

    #[test]
    fn test_reduce_array() {
        let arr = vec![1, 2, 3];
        let initial_value = 0;

        // Test with addition
        let result = reduce_array(&arr, initial_value, |acc, num| *acc += num);
        assert_eq!(result.unwrap(), 6);

        // Test with subtraction
        let result = reduce_array(&arr, initial_value, |acc, num| *acc -= num);
        assert_eq!(result.unwrap(), -6);
    }
}

