        if ($cachedStatus !== false) {
            // Update in cache first
            $this->redisClient->setex("clinic_$clinicId", 60, $status);
            return;
        }

        // 2. API validation and fallback:
        $apiResponses = [];
        foreach ($this->apis as $api) {
            try {
                $response = $api->getClinicStatus($clinicId);
                $apiResponses[] = $response['status'];
            } catch (\Exception $e) {
                // Handle API failures (logging, circuit breaker, etc.)
                $apiResponses[] = 'Unavailable';
            }
        }

        // 3. Concurrent update handling with pessimistic locking:
        $lockId = "clinic_$clinicId_lock";
        if ($this->redisClient->set($lockId, true, ['nx', 'ex' => 60])) { // Acquire lock for 60 seconds
            try {
                // Database update (with batch processing and prepared statements)
                $this->db->updateClinicStatus($clinicId, $status);

                // Update cache after successful database update
                $this->redisClient->setex("clinic_$clinicId", 60, $status);

            } catch (\Exception $e) {
                // Log exception and handle rollback if necessary (see #7)
                throw $e;
            } finally {
                $this->redisClient->del($lockId); // Release lock
            }
        } else {
            // Lock contention - retry or implement a waiting mechanism
        }

        // 4. Logging and tracing:
        $this->logger->info("Clinic status updated for ID $clinicId: $status");
    }

}

