using System;
using System.Xml;

public class ConfigLoader
{
    public static void Main(string[] args)
    {
        // Load configuration settings from XML file
        XmlDocument doc = new XmlDocument();
        doc.Load("config.xml");

        // Extract configuration values
        XmlNode tileNode = doc.SelectSingleNode("//tile");
        int tileSize = int.Parse(tileNode.Attributes["size"].Value);

        XmlNode worldNode = doc.SelectSingleNode("//world");
        int worldWidth = int.Parse(worldNode.Attributes["width"].Value);
        int worldHeight = int.Parse(worldNode.Attributes["height"].Value);

        XmlNode cameraNode = doc.SelectSingleNode("//camera");
        double cameraSpeed = double.Parse(cameraNode.Attributes["speed"].Value);

        // Print extracted values
        Console.WriteLine($"Tile Size: {tileSize}");
        Console.WriteLine($"World Width: {worldWidth}");
        Console.WriteLine($"World Height: {worldHeight}");
        Console.WriteLine($"Camera Speed: {cameraSpeed}");
    }
}
