// C program for integer processing from CSV file
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
  int value;
  struct Node* next;
} Node;

Node* head = NULL;

void add_node(int value) {
  Node* new_node = (Node*)malloc(sizeof(Node));
  new_node->value = value;
  new_node->next = head;
  head = new_node;
}

void process_csv(const char* filename) {
  FILE *fp = fopen(filename, "r");
  char line[1024];

  while (fgets(line, sizeof(line), fp)) {
    // Parse integer value from line
    int value;
    sscanf(line, "%d", &value);
    add_node(value); 
  }
  fclose(fp);
}

void print_list() {
  Node* current = head;
  while (current != NULL) {
    printf("%d ", current->value);
    current = current->next;
  }
  printf("\n");
}

int main() {
  process_csv("integers.csv");
  print_list();
  return 0;
}
```




