['```javascript
async function renderFooterScripts(scriptData, cacheDuration = 60 * 60) {
  const cache = new Map();

  for (const scriptObj of scriptData) {
    if (!scriptObj.id || !scriptObj.code || !scriptObj.type) {
      console.error("Invalid script object:", scriptObj);
      continue; // Skip to the next script
    }

    const cacheKey = `${scriptObj.id}-${scriptObj.type}`;
    if (cache.has(cacheKey)) {
      const cachedScript = cache.get(cacheKey);
      if (Date.now() - cachedScript.timestamp < cacheDuration * 1000) {
        console.log("Using cached script:", cachedScript.id);
        appendScriptTag(cachedScript.code, cachedScript.type);
        continue;
      } else {
        cache.delete(cacheKey); // Remove stale cached entry
      }
    }

    try {
      const response = await fetch(`/validate?script=${encodeURIComponent(scriptObj.code)}`);
      if (!response.ok) {
        console.error(`Validation failed for script ${scriptObj.id}`, response.status);
        continue; // Skip to the next script
      }
      const validationResult = await response.json();

      if (validationResult.isValid) {
        cache.set(cacheKey, { code: scriptObj.code, type: scriptObj.type, timestamp: Date.now() });
        console.log("Validating script:", scriptObj.id);
        appendScriptTag(scriptObj.code, scriptObj.type);
      } else {
        console.error(`Validation failed for script ${scriptObj.id}`, validationResult.message);
      }
    } catch (error) {
      console.error("Error validating script:", error);
      // Implement retry logic and/or fallback mechanism here
    }
  }
}

function appendScriptTag(code, type) {
  const script = document.createElement('script');
  script.type = type;
  script.innerHTML = code;
  document.body.appendChild(script);
} 
```


