// Define asynchronous reduction function with callback
async fn async_reduce<T: std::ops::Add<Output = T>>(numbers: Vec<T>, callback: impl Fn(T) + Send + Sync) {
    let result = futures::future::join_all(numbers.into_iter().map(|num| future::ready(num))).await;
    callback(result.iter().sum());
}

#[cfg(test)]
