  void enqueueLogEvent(const std::string& jsonLogEvent) {
    std::unique_lock<std::mutex> lock(logQueueMutex);
    logQueue.push(jsonLogEvent);
    conditionVariable.notify_one();
  }

private:
  void processLogs() {
    while (running) {
      std::unique_lock<std::mutex> lock(logQueueMutex);
      conditionVariable.wait(lock, [this] { return !logQueue.empty() || !running; });

      if (!running) {
        break; 
      }

      // Process log event from the queue...
      const std::string& jsonEvent = logQueue.front();
      logQueue.pop();
      lock.unlock();

