    std::mutex queueMutex;

    // Simulate sensor data streams
    std::thread sensorThread([&]() {
        for (int i = 0; i < 10; ++i) {
            auto now = std::chrono::system_clock::now();
            SensorData data(i, 25.5 + i * 0.7, now);
            {
                std::lock_guard<std::mutex> lock(queueMutex);
                dataQueue.push(data);
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulate sensor reading interval
        }
    });

    // Data processor thread
    DataProcessor processor;
    std::thread processingThread([&]() {
        while (true) {
            SensorData data; 
