// C++ code for semaphore implementation
#include <mutex> 
#include <condition_variable>

class Semaphore {
public:
    Semaphore(int initialCount = 1) : count_(initialCount), mutex_() {}

    void acquire() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (count_ == 0) {
            cond_.wait(lock);
        }
        --count_;
    }

    void release() {
        std::lock_guard<std::mutex> lock(mutex_);
        ++count_;
        cond_.notify_one();
    }

private:
    int count_;
    std::mutex mutex_;
    std::condition_variable cond_;
};
```


