class DynamicStringManager {
private:
    std::forward_list<std::string> strings;
    std::mutex mutex;

public:
    void insertAfter(const std::string& target, const std::string& toInsert) {
        // Acquire lock for thread safety
        std::lock_guard<std::mutex> lock(mutex); 

        auto it = strings.before_begin(); // Initialize iterator before the list

        for (auto current = strings.begin(); current != strings.end(); ++current) {
            if (*current == target) {
                it = current; // Found target, update iterator
                break;
            } 
        }

        // Insert after the found target or append if not found
        strings.insert_after(it, toInsert);
    }

