    }

    public MoSTState loadState(String stateId, String version) {
        // Retrieve backend and caching strategy from configuration
        StateBackend backend = backendMap.getOrDefault(configManager.getStateBackend(stateId), null);
        if (backend == null) {
            throw new IllegalStateException("Unsupported state backend for " + stateId);
        }

        MoSTState cachedState = cacheManager.getCachedState(stateId, version);
        if (cachedState != null) {
            return cachedState;
        }

        // Load from storage backend and cache
        MoSTState loadedState = backend.loadState(stateId, version);
        cacheManager.cacheState(stateId, version, loadedState);
        return loadedState;
    }

