public class WebhookProcessor {

    private final SchemaRegistry schemaRegistry;
    private final ConnectionPool connectionPool;
    private final RateLimiter rateLimiter;

    public WebhookProcessor(SchemaRegistry schemaRegistry, ConnectionPool connectionPool, RateLimiter rateLimiter) {
        this.schemaRegistry = schemaRegistry;
        this.connectionPool = connectionPool;
        this.rateLimiter = rateLimiter;
    }

    @PostMapping("/webhooks")
    public ResponseEntity<String> processWebhook(@RequestBody String jsonPayload) {
        // Rate limiting check
        if (!rateLimiter.isAllowed()) {
            return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS).body("Rate limit exceeded");
        }

        try {
            // Dynamic schema retrieval and validation
            Schema schema = schemaRegistry.getSchemaByVersion("latest"); 
            JsonNode parsedPayload = ObjectMapper.readValue(jsonPayload, JsonNode.class);
            Validator validator = new JSchemaValidator(schema.toJson());
            validator.validate(parsedPayload);

            // Process webhook data based on schema
            WebhookType type = WebhookType.fromPayload(parsedPayload); 
            switch (type) {
                case PAYMENT_SUCCESS:
                    processPaymentSuccess(parsedPayload);
                    break;
                case ORDER_CREATED:
                    processOrderCreation(parsedPayload);
                    break;
                // ... other webhook types
            }

        } catch (SchemaValidationException e) {
            return ResponseEntity.badRequest().body("Invalid JSON payload");
        } catch (Exception e) {
            // Log error and continue processing
            logger.error("Error processing webhook:", e);
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body("Internal server error");
        }

        return ResponseEntity.ok("Webhook processed successfully");
    }

