  // Configure your S3 credentials and region here
});

const upload = multer({
  // Define file type, size, and other constraints here
  limits: { fileSize: 1024 * 1024 * 5 }, // 5MB limit
  fileFilter: function (req, file, cb) {
    if (file.mimetype === 'image/jpeg' || file.mimetype === 'image/png') {
      cb(null, true);
    } else {
      cb(new Error('Only JPEG and PNG files are allowed.'), false);
    }
  }
});

app.post('/upload', upload.single('file'), async (req, res) => {
  try {
    const file = req.file; 
    const fileName = `${Date.now()}-${file.originalname}`;

    // Encrypt file data before uploading to cloud storage

    const params = {
      Bucket: 'your-bucket-name', // Replace with your bucket name
      Key: fileName,
      Body: file.buffer,
      ACL: 'private' 
    };

    s3.upload(params, (err, data) => {
      if (err) {
        console.error('Error uploading file:', err);
        return res.status(500).send('Upload failed.');
      }

      res.json({ url: data.Location }); // Provide signed URL for access
    }); 
  } catch (error) {
    console.error('Error handling upload:', error);
    res.status(500).send('An error occurred during the upload process.');
  }
});



