public class ServiceConfiguration {

    private static final String CONFIG_FILE = "config.json"; // Path to your configuration file

    public static Map<String, NetworkSettings> readConfig() throws IOException {
        ObjectMapper objectMapper = new ObjectMapper();
        JsonNode rootNode = objectMapper.readTree(new File(CONFIG_FILE));

        Map<String, NetworkSettings> services = new HashMap<>();
        for (JsonNode serviceNode : rootNode.get("services")) {
            String serviceName = serviceNode.get("name").asText();
            NetworkSettings settings = new NetworkSettings();

            // Extract and configure network settings from the JSON configuration
            settings.setIpRange(serviceNode.get("ip_range").asText());
            settings.setDnsServers(serviceNode.get("dns_servers").asTextArray());

            services.put(serviceName, settings);
        }

        return services;
    }

    // NetworkSettings class to hold service-specific network configurations

    public static class NetworkSettings {
        private String ipRange;
        private String[] dnsServers;

