private:
    std::mutex processingMutex;
    std::queue<std::string> messageQueue;
    MessageBroker* broker;
    Storage* storage;
    DistributedTracing* tracing;
    Codec* codec;
public:
    // Constructor
    MessageProcessor(MessageBroker* broker, Storage* storage, DistributedTracing* tracing, Codec* codec) 
        : broker(broker), storage(storage), tracing(tracing), codec(codec) {}

    void processMessages() {
        while (true) {
            std::string message;
            {
                std::lock_guard<std::mutex> lock(processingMutex);
                if (!messageQueue.empty()) {
                    message = messageQueue.front();
                    messageQueue.pop();
                } 
            }

            if (!message.empty()) {
                tracing->startSpan("MessageProcessing");
                // Process the message (e.g., decoding, action based on content)
                std::string processedMessage = process(message);

                // Send to broker and storage
                broker->send(processedMessage); 
                storage->save(processedMessage);

                tracing->endSpan();
            }
        }
    }

private:
    std::string process(const std::string& message) {
        // Implement your message processing logic here
        return codec->decode(message); // Example: Decoding with custom codec
    }

};


