// data_processor.js
const EventEmitter = require('events');
const { Worker } = require('worker_threads');

class DataProcessor extends EventEmitter {
  constructor(sourceFactory, maxConcurrentReads) {
    super();
    this.sourceFactory = sourceFactory;
    this.maxConcurrentReads = maxConcurrentReads;
    this.readWorkers = [];
  }

  async start() {
    const dataStream = this.sourceFactory(); // Get a new data stream from the factory
    for (let i = 0; i < this.maxConcurrentReads; i++) {
      const worker = new Worker('./worker.js', {
        workerData: { dataStream }, // Pass data stream to each worker
      });
      this.readWorkers.push(worker);

      worker.on('message', (data) => this.emit('processed_data', data));
      worker.on('error', (err) => this.emit('error', err));
    }

  }

  stop() {
    // Gracefully shutdown read workers
  }

  // Other methods: pause, resume, etc. 
}


module.exports = DataProcessor;
```

