#include <time.h>

typedef struct {
  int value;
} Record;

int main() {
  // Seed the random number generator
  srand(time(NULL));

  // Allocate memory for long offset values
  long *offsets = malloc(100 * sizeof(long));
  if (offsets == NULL) {
    fprintf(stderr, "Memory allocation failed!\n");
    exit(1);
  }

  // Allocate memory for int keys
  int *keys = malloc(100 * sizeof(int));
  if (keys == NULL) {
    fprintf(stderr, "Memory allocation failed!\n");
    exit(1);
  }

  // Initialize offsets and keys 
  for (int i = 0; i < 100; ++i) {
    offsets[i] = i * 10;
    keys[i] = rand() % 100;
  }

  // Allocate memory for array of records
  Record *records = malloc(100 * sizeof(Record));
  if (records == NULL) {
    fprintf(stderr, "Memory allocation failed!\n");
    exit(1);
  }

  // Set random values for each record
  for (int i = 0; i < 100; ++i) {
    records[i].value = rand() % 100; // Random value between 0 and 99
  }

  // ... Free allocated memory ...
  free(offsets);
  free(keys);
  free(records);

  return 0;
}



