function extractBookNames(text) {
  const oldTestamentBooks = [
    "Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy", "Joshua", 
    "Judges", "Ruth", "1 Samuel", "2 Samuel", "1 Kings", "2 Kings", "1 Chronicles", 
    "2 Chronicles", "Ezra", "Nehemiah", "Esther", "Job", "Psalms", "Proverbs", 
    "Ecclesiastes", "Song of Solomon", "Isaiah", "Jeremiah", "Lamentations", 
    "Ezekiel", "Daniel", "Hosea", "Joel", "Amos", "Obadiah", "Jonah", "Micah", 
    "Nahum", "Habakkuk", "Zephaniah", "Haggai", "Zechariah", "Malachi"
  ];

  const bookNameRegex = new RegExp(`(${oldTestamentBooks.join("|")})`, 'gi');
  let bookCounts = {};

  const matches = text.match(bookNameRegex); // Potential performance improvement with a map for faster lookups if text is very long

  if (matches) {
    for (const match of matches) {
      const bookName = match.toLowerCase(); 
      if (bookCounts[bookName]) {
        bookCounts[bookName]++;
      } else {
        bookCounts[bookName] = 1;
      }
    }
  }

  return bookCounts;
}

```




