    LogProcessor(int max_threads) : 
        max_threads_(max_threads), 
        log_queue_() {}

    void processLog(const std::string& logEntry) {
        std::lock_guard<std::mutex> lock(log_queue_mutex_);
        log_queue_.push(logEntry);
        condition_.notify_one();
    }

    void start() {
        for (int i = 0; i < max_threads_; ++i) {
            threads_.emplace_back([this]() {
                while (true) {
                    std::string logEntry;
                    {
                        std::unique_lock<std::mutex> lock(log_queue_mutex_);
                        condition_.wait(lock, [this]{ return !log_queue_.empty(); });
                        logEntry = log_queue_.front();
                        log_queue_.pop();
                    }

                    // Process the log entry asynchronously 
                    processLogEntry(logEntry); // Implement your processing logic here
