// realtime_data_engine/src/core/DataProcessor.h

#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>

class DataProcessor {
public:
  virtual ~DataProcessor() = default;
  virtual void processData(const std::string& data) = 0;
  virtual bool isHealthy() const = 0;

  void start() {
    processingThread = std::thread(&DataProcessor::processDataLoop, this);
  }

  void stop() {
    stopRequested = true;
    processingThread.join();
  }

private:
  void processDataLoop() {
    while (!stopRequested) {
      std::unique_lock<std::mutex> lock(dataMutex);
      cv.wait(lock, [this] { return !dataQueue.empty() || stopRequested; });
      if (stopRequested) {
        break;
      }

      auto data = std::move(dataQueue.front());
      dataQueue.pop();
      processData(data);
    }
  }

  std::thread processingThread;
  std::queue<std::string> dataQueue;
  std::mutex dataMutex;
  std::condition_variable cv;
  bool stopRequested = false;
};

