    // In a real application, you would use a database or data store here.

    private static List<Product> products = new ArrayList<>();

    static {
        products.add(new Product(1, "Laptop", 1200.0));
        products.add(new Product(2, "Keyboard", 75.0));
    }

    @GetMapping
    public List<Product> getAllProducts() {
        return products;
    }

    @GetMapping("/{id}")
    public Product getProductById(@PathVariable Long id) {
        return products.stream().filter(p -> p.getId().equals(id)).findFirst().orElseThrow(() -> new ResourceNotFoundException("Product not found"));
    }

    @PostMapping
    public Product createProduct(@RequestBody Product product) {
        // Implement validation and business logic here
        products.add(product);
        return product;
    }

    @PutMapping("/{id}")
    public Product updateProduct(@PathVariable Long id, @RequestBody Product updatedProduct) {
        // Implement validation and business logic here
        Product existingProduct = products.stream().filter(p -> p.getId().equals(id)).findFirst().orElseThrow(() -> new ResourceNotFoundException("Product not found"));
        existingProduct.setName(updatedProduct.getName());
        existingProduct.setPrice(updatedProduct.getPrice());
        return existingProduct;
    }

    @DeleteMapping("/{id}")
    public void deleteProduct(@PathVariable Long id) {
        products.removeIf(p -> p.getId().equals(id));
    }
}


class Product {
    private Long id;
    private String name;
    private double price;

    // Constructors, getters and setters
}



