import redis
import threading

class DistributedCache:
    def __init__(self):
        self.nodes = {
            'node1': redis.Redis(host='localhost', port=6379), 
            'node2': redis.Redis(host='localhost', port=6380)
        }
        self.lock = threading.Lock()

    def get(self, key):
        with self.lock:
            for node in self.nodes:
                try:
                    value = self.nodes[node].get(key)
                    if value:
                        return value
                except redis.ConnectionError:
                    print(f"Connection error to node {node}")
                    continue
        return None  

    def set(self, key, value, ttl=60):
        with self.lock:
            for node in self.nodes:
                try:
                    self.nodes[node].set(key, value, ex=ttl)
                    print(f"Value '{value}' set for key '{key}' on node {node}")
                    return True
                except redis.ConnectionError:
                    print(f"Connection error to node {node}")
                    continue
            return False

    def delete(self, key):
        with self.lock:
            for node in self.nodes:
                try:
                    self.nodes[node].delete(key)
                    print(f"Key '{key}' deleted from node {node}")
                    return True
                except redis.ConnectionError:
                    print(f"Connection error to node {node}")
                    continue
            return False

