#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>

class DistributedSemaphore {
public:
    DistributedSemaphore(const std::string& name, int initialCount) : 
        m_name(name), m_count(initialCount) {
        // Initialization logic based on environment variables or config files
    }

    bool acquire() {
        std::unique_lock<std::mutex> lock(m_mutex);
        m_cv.wait(lock, [this]{ return m_count > 0; });
        --m_count;
        return true;
    }

    void release() {
        std::lock_guard<std::mutex> lock(m_mutex);
        ++m_count;
        m_cv.notify_one(); 
    }

private:
    std::string m_name;
    int m_count;
    std::mutex m_mutex;
    std::condition_variable m_cv;
};


// C function for modifying filenames
void safeModifyFilename(char* filename, const char* suffix) {
    char buffer[256]; // Ensure sufficient buffer size
    sprintf(buffer, "%s_%d%s", filename, rand() % 100, suffix);  
