public static Process StartWebsite(string directoryPath, string siteName)
{
    if (!Directory.Exists(directoryPath))
    {
        return null; 
    }

    string configPath = Path.Combine(directoryPath, "web.config");
    if (!File.Exists(configPath))
    {
        return null;
    }

    // Construct the process start information
    string startInfo = $"\"{Path.Combine(directoryPath, "start.bat")}\""; // Assuming a start script exists

    ProcessStartInfo processInfo = new ProcessStartInfo()
    {
        WorkingDirectory = directoryPath,
        FileName = "cmd.exe", 
        Arguments = startInfo, 
        UseShellExecute = false,
        RedirectStandardOutput = true,
        RedirectStandardError = true
    };

    Process process = new Process();
    process.StartInfo = processInfo;

    if (process.Start())
    {
        Console.WriteLine($"Started website {siteName} at: {directoryPath}"); 
        return process;
    }
    else
    {
        Console.WriteLine($"Failed to start website {siteName} at: {directoryPath}");
        return null;
    } 
}   
