#include <iostream>
#include <thread>  
#include <queue>    
#include <mutex>   
#include <condition_variable>

class MessageProcessor {
public:
    MessageProcessor(const std::string& name) : name_(name), running_(true) {}

    void Start() {
        std::thread worker([this]() {
            while (running_) {
                // Process messages from the queue
                std::unique_lock<std::mutex> lock(queueMutex_);
                cv_.wait(lock, [this]{return !messageQueue_.empty();});

                auto message = std::move(messageQueue_.front());
                messageQueue_.pop();
                lock.unlock();

                // Handle the message (e.g., log it, send a response)
                std::cout << name_ << ": Processing message: " << message << std::endl;
            }
        });
        worker.detach();
    }

    void Stop() {
        running_ = false;
    }

    void EnqueueMessage(const std::string& message) {
        std::lock_guard<std::mutex> lock(queueMutex_);
        messageQueue_.push(message);
        cv_.notify_one(); // Wake up the worker thread
    }

private:
    std::string name_;
    bool running_;
    std::queue<std::string> messageQueue_;
    std::mutex queueMutex_;
    std::condition_variable cv_;
};


int main() {
    MessageProcessor processor("Main Processor");
    processor.Start();

    // Simulate sending messages 
    for (int i = 0; i < 10; ++i) {
        processor.EnqueueMessage("Message " + std::to_string(i));
    }

    std::this_thread::sleep_for(std::chrono::seconds(5)); // Let the processor work for a bit

    processor.Stop();

    return 0;
}



