        executor.execute(() -> {
            while (true) {
                try {
                    startService();
                    LOGGER.info("Service started");
                    Thread.sleep(new Random().nextInt(5000)); // Random delay between starts
                } catch (InterruptedException e) {
                    LOGGER.error("Service interruption:", e); 
                } finally {
                    stopService();
                    LOGGER.info("Service stopped");

                    // Send message to messaging system
                    sendMessageToQueue();
                }
            }
        });

        executor.shutdown();
    }

