function traverseDOM(node, selector, testFunction) {
  const results = [];
  if (testFunction(node)) {
    results.push(node);
  }
  for (let i = 0; i < node.children.length; i++) {
    results.push(...traverseDOM(node.children[i], selector, testFunction));
  }
  return results;
}
