    private $authConfig;
    private $hashingAlgorithm = 'PASSWORD_BCRYPT';

    public function __construct(array $config)
    {
        $this->authConfig = $config;
    }

    public function generateSecureRandomString($length, $charset) 
    {
        // Validate character set
        if (!preg_match('/[a-z]/', $charset) || !preg_match('/[A-Z]/', $charset) || !preg_match('/\d/', $charset) || !preg_match('/[!@#$%^&*()_+~`|}{\[\]:";'<>,.?\/]/', $charset)) {
            throw new InvalidArgumentException('Character set must include lowercase, uppercase, digit, and special character.');
        }

        $attempts = 0;
        while ($attempts < 100) {
            $randomString = random_bytes($length);
            $string = bin2hex($randomString);
            return $string;
        }
        throw new RuntimeException('Failed to generate secure random string after 100 attempts.');

    }

    public function hashPassword($password)
    {
        return password_hash($password, $this->hashingAlgorithm);
    }

    public function verifyPassword($plainTextPassword, $hashedPassword)
    {
        return password_verify($plainTextPassword, $hashedPassword);
    }

