#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>
#include <map>

class SensorData {
public:
    int id;
    double value;
    std::string timestamp;

    SensorData(int id, double value, const std::string& timestamp) 
        : id(id), value(value), timestamp(timestamp) {}
};

// Simplified data pipeline
class DataPipeline {
public:
    void ingest(const SensorData& data) {
        std::lock_guard<std::mutex> lock(dataMutex);
        dataQueue.push(data);
        cv.notify_one(); // Notify worker threads 
    }

private:
    std::queue<SensorData> dataQueue;
    std::mutex dataMutex;
    std::condition_variable cv;

    void processData() {
        while (true) {
            std::unique_lock<std::mutex> lock(dataMutex);
            cv.wait(lock, [this] { return !dataQueue.empty(); }); 

            SensorData data = dataQueue.front();
            dataQueue.pop();
            lock.unlock();

            // Process the data here (e.g., transformation, analysis)
            std::cout << "Processing: " << data.id << ", " << data.value << std::endl; 
        }
    }
};

int main() {
    DataPipeline pipeline;

    // Start worker threads for processing
    std::vector<std::thread> workers;
    for (int i = 0; i < 4; ++i) { // Example: 4 worker threads
        workers.emplace_back(std::ref(pipeline), &DataPipeline::processData);
    }

    // Simulate sensor data ingestion
    for (int i = 0; i < 10; ++i) {
        pipeline.ingest({i, i * 2.5, "2023-10-27T" + std::to_string(i)});
    }

    // Wait for workers to complete
    for (auto& worker : workers) {
        worker.join();
    }

    return 0;
}

```




