class Semaphore {
public:
    Semaphore(const std::string& name, int initialCount) : 
        m_name(name), m_count(initialCount), m_mutex() {}

    // Acquire semaphore lock
    bool acquire() {
        std::unique_lock<std::mutex> lock(m_mutex);
        m_cv.wait(lock, [this] { return m_count > 0; });
        --m_count;
        return true;
    }

    // Release semaphore lock
    void release() {
        std::lock_guard<std::mutex> lock(m_mutex);
        ++m_count;
        m_cv.notify_one(); 
    }

private:
    std::string m_name; // Semaphore name for identification and logging
    int m_count;      // Current count of available permits
    std::mutex m_mutex;   // Mutex to protect shared state
    std::condition_variable m_cv;  // Condition variable for waiting threads

    // ... (Additional methods for dynamic initialization, error handling, etc.) ...
};


